// Team 0 (the player's team) scores: add the goal, log it in the first
// half at the current minute, then let team 1 kick off.
local time = CMND_BTL_GET_MATCH_TIME();
CMND_BTL_ADD_POINT([1, 0]);
CMND_BTL_SET_POINT_HISTORY(0, 0, time / 60, format("para_cp%04d", idKageyama));
CMND_BTL_SET_MATCH_RESTART(1);

// Team 1 (the opponent) scores in the second half at minute 5, then the
// match continues from 5:00 in the second half.
CMND_BTL_SET_POINT_HISTORY(1, 1, 5, "para_cp0069");
CMND_BTL_SET_MATCH_PHASE(1, 300);

// After the event scene, team 1 gets a goal in minute 1 of the first
// half, and team 0 kicks off again.
CMND_BTL_SET_EVPARAM(44040010);
suspend();
CMND_BTL_ADD_POINT([0, 1]);
CMND_BTL_SET_POINT_HISTORY(1, 0, 1, "para_cp0010", true);
CMND_BTL_SET_MATCH_RESTART(0);
